<script setup lang="ts">
import { computed } from 'vue'
import { useNavigation } from '../stores/navigation'
import { useLearning } from '../stores/learning'
import { readings } from '../data/content'
import { lastSevenDays } from '../lib/dates'
import ReadingCard from '../components/ReadingCard.vue'
import AppIcon from '../components/AppIcon.vue'
import StageList from '../components/StageList.vue'
const nav=useNavigation(), store=useLearning()
const todayLabel=computed(()=>new Intl.DateTimeFormat('id-ID',{weekday:'long',day:'numeric',month:'long'}).format(new Date(`${store.todayKey}T12:00:00`)))
const reading=readings[0]!
const days=computed(()=>lastSevenDays(store.todayKey).map(day=>({key:day,label:new Intl.DateTimeFormat('id-ID',{weekday:'short'}).format(new Date(`${day}T12:00:00`)),minutes:Math.round((store.state.days[day]?.seconds||0)/60)})))
const maxMinutes=computed(()=>Math.max(10,...days.value.map(d=>d.minutes)))
const targets=[{id:'read' as const,label:'Baca satu pelajaran'},{id:'quiz' as const,label:'Kerjakan kuis singkat'},{id:'review' as const,label:'Ulangi satu bacaan'}]
const pending=computed(()=>store.state.questions.filter(q=>!q.answered).slice(-2))
</script>
<template><div class="page-heading"><div><p class="eyebrow">BELAJAR DENGAN TENANG</p><h1>Assalamu’alaikum{{store.state.settings.name?`, ${store.state.settings.name}`:'.'}}</h1><p>Perjalanan yang baik dimulai dari satu langkah kecil.</p></div><span class="date-label">{{todayLabel}}</span></div><div class="dashboard-grid"><div class="main-column"><section class="hero"><div class="progress-ring" :style="{'--progress':store.percent+'%'}" role="img" :aria-label="`Progres keseluruhan ${store.percent} persen`"><span>{{store.percent}}<small>%</small></span></div><div class="hero-copy"><span class="hero-eyebrow">BISMILLAH, MARI {{store.completed.length?'LANJUTKAN':'MULAI'}}</span><h2>Lanjutkan perjalananmu</h2><p>{{store.nextLesson.title}} · {{store.nextLesson.minutes}} menit<br/>{{store.completed.length}} dari {{store.totalPlanned}} rencana pelajaran selesai.</p><button class="button cream" @click="nav.go('lesson',store.nextLesson.id)">{{store.completed.length===2?'Baca kembali pelajaran':'Lanjutkan pelajaran'}}<AppIcon name="arrow" :size="17"/></button></div><span class="hero-decoration" aria-hidden="true">✧</span></section><StageList :completed="store.completed"/><section class="card"><div class="section-header"><h2>Aktivitas minggu ini</h2><span class="muted text-sm">{{days.reduce((n,d)=>n+d.minutes,0)}} menit / 7 hari</span></div><div class="chart" role="img" :aria-label="days.map(d=>`${d.label}: ${d.minutes} menit`).join(', ')"><div v-for="day in days" :key="day.key" class="chart-col" :title="`${day.minutes} menit`"><span v-if="day.minutes" class="chart-value">{{day.minutes}}</span><div :class="['chart-bar',{'empty-bar':!day.minutes}]" :style="{height:Math.max(4,day.minutes/maxMinutes*76)+'px'}"></div><span :class="{'today-label':day.key===store.todayKey}">{{day.label}}</span></div></div><p class="small-note">Tidak apa-apa melewatkan satu hari. Lanjutkan saat siap.</p></section></div><aside class="today-column" aria-label="Hari ini"><div class="today-heading"><AppIcon name="sun" :size="17"/>HARI INI</div><ReadingCard :reading="reading" compact/><section class="card"><div class="section-header"><p class="eyebrow mb-0">TARGET HARI INI</p><span class="badge neutral">{{Math.floor(store.today.seconds/60)}} / {{store.state.settings.dailyMinutes}} menit</span></div><label v-for="target in targets" :key="target.id" class="check-row"><input type="checkbox" :checked="store.today.goals.includes(target.id)" @change="store.toggleGoal(target.id)"/>{{target.label}}</label><div class="progress-track" role="progressbar" aria-label="Target harian" :aria-valuenow="store.today.goals.length" aria-valuemin="0" aria-valuemax="3"><span :style="{width:store.today.goals.length/3*100+'%'}"></span></div><p class="small-note">{{store.today.goals.length}} dari 3 selesai. Sedikit demi sedikit.</p></section><section class="card"><p class="eyebrow">PERTANYAAN UNTUK GURU</p><template v-if="pending.length"><p v-for="q in pending" :key="q.id" class="question-preview">{{q.text}}</p></template><p v-else class="muted text-sm">Ada yang belum dipahami? Simpan untuk ditanyakan saat bertemu guru.</p><button class="button dashed full" @click="nav.go('notes')"><AppIcon name="plus" :size="16"/>Catat pertanyaan</button></section><div class="encouragement"><AppIcon name="leaf" :size="20"/><p>{{store.streak.current?`${store.streak.current} hari beruntun belajar.`:'Selalu ada ruang untuk memulai lagi.'}}<br/><strong>Ritme terbaik: {{store.streak.best}} hari · {{store.streak.totalDays}} hari bertumbuh.</strong></p></div></aside></div></template>
